\begin{editorial}
  This chapter covers the metatheory of epistemic logics. It is structured in a similar way to Aldo Antonelli's notes on classical  basic modal logic, but has been rewritten by Audrey Yap in order to add material on bisimulation and dynamic epistemic logics.
\end{editorial}

For the second proof, suppose again that $A$ is enumerated by~$f$ and
$B$ is enumerated by~$g$. Let
\[
k(x) = \begin{cases}
f(x/2) & \text{if $x$ is even} \\
g((x-1)/2) & \text{if $x$ is odd.}
\end{cases}
\]
Then $k$ enumerates $A \cup B$; the idea is that $k$ just alternates
between the enumerations offered by $f$ and~$g$. Enumerating $A \cap
B$ is tricker. If $A \cap B$ is empty, it is trivially computably
enumerable. Otherwise, let $c$ be any element of $A \cap B$, and
define $l$ by
\[
l(x) = \begin{cases}
f((x)_0) & \text{if $f((x)_0) = g((x)_1)$} \\
c & \text{otherwise.}
\end{cases}
\]
In computational terms, $l$ runs through pairs of elements in the
enumerations of $f$ and $g$, and outputs every match it finds;
otherwise, it just stalls by outputting $c$.

\begin{defn}
  A \emph{model} for temporal language is a triple
  $\mModel{M} = \tuple{T, \prec, V}$, where
  \begin{enumerate}
  \item $T$ is a nonempty set, interpreted as points in time.
  \item $\prec$ is a binary relation on $T$.
  \item $V$ is a function assigning to each !!{propositional
    variable}~$p$ a set $V(p)$ of points in time.
  \end{enumerate}
  When $t \prec t'$ holds, we say that $t$ \emph{precedes}~$t'$. 
  When $t \in V(p)$ we say $p$ is \emph{true at}~$t$.
\end{defn}

\begin{defn}[Theorems]
!!^a{formula}~$!A$ is a \emph{theorem} if there is !!a{derivation}
of~$!A$ from the empty set.  We write $\Proves !A$ if $!A$ is a
theorem and $\Proves/ !A$ if it is not.
\end{defn}

\begin{prop}[Compactness]
\ollabel{prop:proves-compact}
  \begin{enumerate}
  \item If $\Gamma \Proves !A$ then there is a finite subset $\Gamma_0
    \subseteq \Gamma$ such that $\Gamma_0 \Proves !A$.
  \item If every finite subset of~$\Gamma$ is
    consistent, then $\Gamma$ is consistent.
  \end{enumerate}
\end{prop}

\begin{proof} Any finite $\Gamma_0 \subseteq \Gamma$ is also a finite
subset of~$\Delta$, so !!a{derivation} of $\Gamma_0 \Proves !A$ also shows
$\Delta \Proves !A$. \end{proof}

\begin{defn}\ollabel{defn:DedekindInfinite}
A set $A$ is \emph{Dedekind infinite} iff there is !!a{injection}
from~$A$ to a proper subset of~$A$. That is, there is some $o \in A$
and !!a{injection} $f \colon A \to A$ such that $o \notin \ran{f}$.
\end{defn}

\begin{prop}
The !!{formula}
  \[
  \fn{Codes}(x, R, Z) \ident \lforall[y][(Z(y) \liff
    R(x, y))]
  \]
expresses that $s(x)$ $s(R)$-codes $s(Z)$.  The
!!{formula} 
\begin{multline*}
  \fn{Pow}(Y, R, X) \ident \\
  \lforall[Z][(Z \subseteq X \lif \lexists[x][(Y(x) \land
    \fn{Codes}(x, R, Z))])] \land {} \\ \lforall[x][(Y(x) \lif
  \lforall[Z][(\fn{Codes}(x, R, Z) \lif Z \subseteq X)]]
\end{multline*}
expresses that $s(Y)$ $s(R)$-codes the power set of~$s(X)$, i.e., the
elements of $s(Y)$ $s(R)$-code exactly the subsets of $s(X)$.
\end{prop}

\begin{thm}
\ollabel{thm:ce-comp}
Let $A$ be any set of natural numbers. Then $A$ is computable if and
only if both $A$ and $\Complement{A}$ are computably enumerable.
\end{thm}

\begin{defn}
  Let $S$ be a set of natural numbers. Then $S$ is \emph{computable}
  iff its characteristic function~$\Char{S}$ is. In other words,
  $S$~is computable iff the function
\[
\Char{S}(x) =
\begin{cases}
1 & \text{if $x \in S$} \\
0 & \text{otherwise}
\end{cases}
\]
is computable. Similarly, a relation $R(x_0, \dots, x_{k-1})$ is
computable if and only if its characteristic function is.

\begin{thm}
\ollabel{thm:ce-equiv}
Let $S$ be a set of natural numbers. Then the following are
equivalent:
\begin{enumerate}
\item\ollabel{case:ce} $S$ is computably enumerable.
\item\ollabel{case:ran-pc} $S$ is the range of a \emph{partial} computable function.
\item\ollabel{case:ran-prim} $S$ is empty or the range of a primitive recursive function.
\item\ollabel{case:ce-domain} $S$ is the \emph{domain} of a partial computable function.
\end{enumerate}
\end{thm}

