\begin{prop}\ollabel{wo:strictorder}
If $<$ well-orders $A$, then every non-empty subset of $A$ has a unique
$<$-least member, and $<$ is irreflexive, asymmetric and transitive.
\end{prop}

\begin{prop}
  \ollabel{prop:derivfacts}
\begin{enumerate}
\item $\Proves (!A \lif !B) \lif ((!B \lif !C)
  \lif (!A \lif !C)$; \ollabel{derivfacts:a}
\item If $\Gamma \cup \{ \lnot !A\}
  \Proves \lnot !B$ then $\Gamma \cup \{ !B\} \Proves
  !A$ (Contraposition); \ollabel{derivfacts:b}
\item  $\{ !A, \lnot!A\} \Proves
    !B$ (Ex Falso Quodlibet, Explosion); \ollabel{derivfacts:c}
\item  $\{ \lnot\lnot!A\} \Proves
  !A$ (Double Negation Elimination);\ollabel{derivfacts:d}
\item If $\Gamma \Proves \lnot\lnot!A$ then $\Gamma \Proves
  !A$;\ollabel{derivfacts:e}
\end{enumerate}
\end{prop}

\begin{proof}
  \begin{enumerate}
    \item If $\Gamma \Proves !A$, then there is a finite sequence of
      !!{formula}s $!A_1$, \dots,~$!A_n$ so that $!A \ident !A_n$ and
      each $!A_i$ is either a logical axiom, !!a{element} of~$\Gamma$
      or follows from previous !!{formula}s by modus ponens.  Take
      $\Gamma_0$ to be those $!A_i$ which are in~$\Gamma$.  Then the
      !!{derivation} is likewise !!a{derivation} from~$\Gamma_0$, and
      so $\Gamma_0 \Proves !A$.
    \item This is the contrapositive of~(1) for the special case $!A
      \ident \lfalse$.
\end{enumerate}
\end{proof}

\begin{prop}[Reflexivity]
\ollabel{prop:reflexivity}
If $!A \in \Gamma$, then $\Gamma \Proves !A$.
\end{prop}

\begin{prop}[Transitivity]
\ollabel{prop:transitivity}
If $\Gamma \Proves !A$ and $\{!A\} \cup \Delta \Proves
!B$, then $\Gamma \cup \Delta \Proves !B$.
\end{prop}

We are now also in a position to give truth conditions for the common
knowledge operator~$\CKnows_G$. Recall from \olref[sfr][rel][ops]{sec}
that the \emph{transitive closure}~$R^+$ of a relation~$R$ is defined
as
\begin{align*}
  R^+ &= \bigcup_{ n \in \mathbb{N}} R^n, 
\intertext{where}
  R^0 & = R \text{ and}\\ 
  R^{n+1} & = \Setabs{\tuple{x, z}}{\exists y (R^n xy \land Ryz)}.
\end{align*}
Then, where $G$ is a group of agents, we define $R_G = ( \bigcup_{b
\in G} R_b )^+$ to be the transitive closure of the union of all
agents' accessibility relations.

\begin{prop}
The function $\fn{concat}(s,t)$, which concatenates two
sequences, is primitive recursive.
\end{prop}

\begin{prop}
  Let $R$ be an equivalence relation, and for each $w \in W$ define
  the \emph{equivalence class} of $w$ as the set $[w] = \{w'\in W :
  Rww'\}$. Then:
  \begin{enumerate}
  \item $w \in [w]$;
  \item $R$ is universal on each equivalence class $[w]$;
  \item The collection of equivalence classes partitions $W$ into mutually
    exclusive and jointly exhaustive subsets.
  \end{enumerate}
\end{prop}

