We are only a couple of steps away from the proof of the fixed-point
theorem. Suppose a variant of the print function $\fn{print}(x,y)$
accepts a string $x$ and another numeric argument $y$, and prints the
string $x$ repeatedly, $y$ times. Then the ``program''
\begin{quote}
\begin{verbatim}
getinput(y);
print(diag('getinput(y); print(diag(x), y)'), y)
\end{verbatim}
\end{quote}
prints itself out $y$ times, on input $y$. Replacing the
$\fn{getinput}$---$\fn{print}$---$\fn{diag}$ skeleton by an
arbitrary function $g(x,y)$ yields
\begin{quote}
\begin{verbatim}
g(diag('g(diag(x), y)'), y)
\end{verbatim}
\end{quote}
which is a program that, on input $y$, runs $g$ on the program itself
and $y$. Thinking of ``quoting'' with ``using an index for,'' we have
the proof above.

\begin{explain}
Notice that we now have a number of notions of computability: for
partial functions, for functions, and for sets. Do not get them
confused!{} \iftag{TMs}{The Turing machine computing a partial function
  returns the output of the function, for input values at which the
  function is defined; the Turing machine computing a set returns
  either $1$ or~$0$, after deciding whether or not the input value is in
  the set or not.}{}
\end{explain}

\begin{defn}\ollabel{defn:mmodels} \emph{Truth of !!a{formula}~$!A$
  at~$w$} in a~$\mModel M = \tuple{W, R, V}$, in symbols:
  $\mSat{M}{!A}[w]$, is defined inductively as follows:
  \begin{enumerate}
  \tagitem{prvFalse}{\indcase{!A}{\lfalse}{Never $\mSat{M}{\lfalse}[w]$}.}{}
  \tagitem{prvTrue}{\indcase{!A}{\ltrue}{Always $\mSat{M}{\ltrue}[w]$}.}{}
  \item $\mSat{M}{p}[w]$ iff $w \in V(p)$
  \tagitem{prvNot}{\indcase{!A}{\lnot !B}{$\mSat{M}{\indfrm}[w]$ iff
    $\mSat/{M}{!B}[w]$}.}{}
  \tagitem{prvAnd}{\indcase{!A}{(!B \land !C)}{$\mSat{M}{\indfrm}[w]$ iff
    $\mSat{M}{!B}[w]$ and $\mSat{M}{!C}[w]$}.}{}
  \tagitem{prvOr}{\indcase{!A}{(!B \lor !C)}{$\mSat{M}{\indfrm}[w]$ iff
    $\mSat{M}{!B}[w]$ or $\mSat{M}{!C}[w]$} (or both).}{}
  \tagitem{prvIf}{\indcase{!A}{(!B \lif !C)}{$\mSat{M}{\indfrm}[w]$ iff
    $\mSat/{M}{!B}[w]$ or $\mSat{M}{!C}[w]$}.}{}
  \tagitem{prvIff}{\indcase{!A}{(!B \liff !C)}{$\mSat{M}{\indfrm}[w]$ iff
    either both $\mSat{M}{!B}[w]$ and $\mSat{M}{!C}[w]$ or
    neither $\mSat{M}{!B}[w]$ nor $\mSat{M}{!C}[w]$}.}{}
  \item\ollabel{defn:sub:mmodels-box}
    \indcase{!A}{\Knows_a !B}{$\mSat{M}{\indfrm}[w]$ iff
    $\mSat{M}{!B}[w']$ for all $w' \in W$ with $R_a ww'$}
  \item\ollabel{defn:sub:mmodels-pal}
    \indcase{!A}{[!B] !C}{$\mSat{M}{\indfrm}[w]$ iff
    $\mSat{M}{!B}[w]$ implies $\mSat{M \mid !B}{!C}[w]$}

\begin{defn}\ollabel{defn:mmodels}
  \emph{Truth of !!a{formula}~$!A$ at~$w$} in a~$\mModel M$, in symbols:
  $\mSat{M}{!A}[w]$, is defined inductively as follows:
  \begin{enumerate}
  \tagitem{prvFalse}{\indcase{!A}{\lfalse}{Never $\mSat{M}{\lfalse}[w]$}.}{}
  \tagitem{prvTrue}{\indcase{!A}{\ltrue}{Always $\mSat{M}{\ltrue}[w]$}.}{}
  \item $\mSat{M}{p}[w]$ iff $w \in V(p)$
  \tagitem{prvNot}{\indcase{!A}{\lnot !B}{$\mSat{M}{\indfrm}[w]$ iff
    $\mSat/{M}{!B}[w]$}.}{}
  \tagitem{prvAnd}{\indcase{!A}{(!B \land !C)}{$\mSat{M}{\indfrm}[w]$ iff
    $\mSat{M}{!B}[w]$ and $\mSat{M}{!C}[w]$}.}{}
  \tagitem{prvOr}{\indcase{!A}{(!B \lor !C)}{$\mSat{M}{\indfrm}[w]$ iff
    $\mSat{M}{!B}[w]$ or $\mSat{M}{!C}[w]$} (or both).}{}
  \tagitem{prvIf}{\indcase{!A}{(!B \lif !C)}{$\mSat{M}{\indfrm}[w]$ iff
    $\mSat/{M}{!B}[w]$ or $\mSat{M}{!C}[w]$}.}{}
  \tagitem{prvIff}{\indcase{!A}{(!B \liff !C)}{$\mSat{M}{\indfrm}[w]$ iff
    either both $\mSat{M}{!B}[w]$ and $\mSat{M}{!C}[w]$ or
    neither $\mSat{M}{!B}[w]$ nor $\mSat{M}{!C}[w]$}.}{}
  \item\ollabel{defn:sub:mmodels-box}
    \indcase{!A}{\Knows_a !B}{$\mSat{M}{\indfrm}[w]$ iff
    $\mSat{M}{!B}[w']$ for all $w' \in W$ with $R_a ww'$}
  \end{enumerate} 
\end{defn}

