\begin{defn}
Two natural numbers $a$ and $b$ are \emph{relatively prime} iff their
greatest common divisor is~$1$; in other words, they have no other
divisors in common.
\end{defn}

Here is Sunzi's Theorem:
\begin{thm}
Suppose $x_0$, \dots,~$x_n$ are (pairwise) relatively prime. Let
$y_0$, \dots,~$y_n$ be any numbers. Then there is a number $z$ such that
\begin{align*}
z & \equiv y_0 \mod x_0 \\
z & \equiv y_1 \mod x_1 \\
& \vdots  \\
z & \equiv y_n \mod x_n.
\end{align*}
\end{thm}

\begin{prop}
  The set of primitive recursive relations is closed under bounded
  quantification, i.e., if $R(\vec x, z)$ is a primitive recursive
  relation, then so are the relations
  \begin{align*}
    & \bforall{z < y}{R(\vec x, z)} \text{ and}\\
    & \bexists{z < y}{R(\vec x, z)}.
  \end{align*}
  $\bforall{z < y}{R(\vec x, z)}$ holds of $\vec x$ and $y$ if and
  only if $R(\vec x, z)$ holds for every~$z$ less than~$y$, and
  similarly for $\bexists{z < y}{R(\vec x, z)}$.
\end{prop}

\begin{defn}[Axioms for quantifiers]
The \emph{axioms} governing quantifiers are
all instances of the following:
\begin{align}
\ollabel{ax:q1} & \lforall[x][!B] \lif !B(t), \\
\ollabel{ax:q2} & !B(t) \lif \lexists[x][!B].
\end{align}
for any closed term~$t$.
\end{defn}

\begin{defn}[Axioms for !!{identity}]
\begin{align}
\ollabel{ax:id1} & \eq[t][t], \\
\ollabel{ax:id2} & \eq[t_1][t_2] \lif (!B(t_1) \lif
  !B(t_2)),
\end{align}
for any closed terms $t$, $t_1$, $t_2$.
\end{defn}

\begin{prop}\ollabel{prop:iden1}
 $\Gamma \Proves \eq[t][t]$, for any term $t$ and set~$\Gamma$.
\end{prop}

\begin{lem}
There is no ``universal computable relation.'' That is, there is no
binary computable relation $R(x,y)$, with the following property:
whenever $S(y)$ is a unary computable relation, there is some $k$ such
that for every $y$, $S(y)$ is true if and only if $R(k,y)$ is true.
\end{lem}

