It is generally useful to be able to define functions in terms of
themselves. For example, given computable functions $k$, $l$, and~$m$,
the fixed-point lemma tells us that there is a partial computable
function~$f$ satisfying the following equation for every~$y$:
\[
f(y) \simeq
\begin{cases}
k(y) & \text{if $l(y) = 0$} \\
f(m(y)) & \text{otherwise.}
\end{cases}
\]
Again, more specifically, $f$~is obtained by letting
\[
g(x,y) \simeq
\begin{cases}
k(y) & \text{if $l(y) = 0$} \\
\cfind{x}(m(y)) & \text{otherwise}
\end{cases}
\]
and then using the fixed-point lemma to find an index~$e$ such that
$\cfind{e}(y) = g(e,y)$.

\begin{prop}
The relation $\fn{Atom}(x)$ which holds iff $x$ is the G\"odel number
of an atomic !!{formula}, is primitive recursive.
\end{prop}

\begin{proof}
The number $x$ is the G\"odel number of an atomic !!{formula} iff
one of the following holds:
\begin{enumerate}
\item There are $n$, $j < x$, and $z < x$ such that for each $i < n$,
  $\fn{Term}((z)_i)$ and $x = $
\[
\Gn{\Obj P^n_j(} \concat \fn{flatten}(z) \concat \Gn{)}.
\]
\item There are $z_1, z_2 < x$ such that $\fn{Term}(z_1)$,
  $\fn{Term}(z_2)$, and $x = $
\[
\Gn{{\eq}(} \concat z_1 \concat \Gn{,} \concat z_2 \concat{\Gn{)}}.
\]
  \tagitem{prvFalse}{$x = \Gn{\lfalse}$.}{}
  \tagitem{prvTrue}{$x = \Gn{\ltrue}$.}{}
\end{enumerate}
\end{proof}

\begin{prop}
\ollabel{prop:frm-primrec}
The relation $\fn{Frm}(x)$ which holds iff $x$ is the G\"odel number
of !!a{formula} is primitive recursive.
