\begin{thm}[in $\ZF$]\ollabel{choiceset}
Choice is equivalent to the following principle. If the !!{element}s
of $A$ are disjoint and non-empty, then there is some $C$ such that $C
\cap x$ is a singleton for every $x \in A$. (We call such a $C$ a
{choice set} for $A$.)
\end{thm}

\begin{prop}
  Let $R$ be an equivalence relation, and for each $w \in W$ define
  the \emph{equivalence class} of $w$ as the set $[w] = \{w'\in W :
  Rww'\}$. Then:
  \begin{enumerate}
  \item $w \in [w]$;
  \item $R$ is universal on each equivalence class $[w]$;
  \item The collection of equivalence classes partitions $W$ into mutually
    exclusive and jointly exhaustive subsets.
  \end{enumerate}
\end{prop}

